import pytest
import web

from openlibrary.catalog.add_book import load_book
from openlibrary.mocks.mock_infobase import MockSite
from openlibrary.mocks.mock_infobase import mock_site  # noqa: F401 (fixture)


def author(key, name, **kwargs):
    doc = {
        'key': f'/authors/OL{key}A',
        'type': {'key': '/type/author'},
        'name': name,
    }
    doc.update(kwargs)
    return doc


class TestRegexILike:
    @pytest.mark.parametrize(
        'pattern,text,expected',
        [
            ('John Smith', 'john smith', True),
            ('john smith', 'John Smith', True),
            ('John Smith', 'John Smithson', False),  # whole string match
            ('John*', 'John Smith', True),
            ('John*', 'jon smith', False),
            ('*Doyle*', 'Arthur Conan Doyle', True),
            ('Doyle', 'Arthur Conan Doyle', False),
            ('a_b', 'a_b', True),  # _ is not a wildcard
            ('a_b', 'axb', False),
            ('*', 'anything', True),
        ],
    )
    def test_regex_ilike(self, pattern, text, expected):
        assert MockSite.regex_ilike(pattern, text) is expected


class TestFindAuthor:
    def test_case_insensitive_name(self, mock_site):
        mock_site.save(author(1, 'Mark Twain'))
        assert load_book.find_author({'name': 'mark TWAIN'})[0]['key'] == '/authors/OL1A'
        assert load_book.find_entity({'name': 'mark TWAIN'})['key'] == '/authors/OL1A'

    def test_name_with_dates_beats_other_matches(self, mock_site):
        mock_site.save(author(1, 'Mark Twain', birth_date='1835', death_date='1910'))
        mock_site.save(author(2, 'Mark Twain', birth_date='1835', death_date='1912'))
        found = load_book.find_author(
            {'name': 'mark twain', 'birth_date': '1835', 'death_date': '1910'}
        )
        assert [a['key'] for a in found] == ['/authors/OL1A']

    def test_only_year_is_compared(self, mock_site):
        mock_site.save(
            author(1, 'Mark Twain', birth_date='b. 1835', death_date='d. 1910')
        )
        found = load_book.find_author(
            {'name': 'Mark Twain', 'birth_date': '1835', 'death_date': '1910.'}
        )
        assert [a['key'] for a in found] == ['/authors/OL1A']

    def test_year_difference_invalidates_match(self, mock_site):
        mock_site.save(author(1, 'Mark Twain', birth_date='1835', death_date='1910'))
        found = load_book.find_author(
            {'name': 'Mark Twain', 'birth_date': '1835', 'death_date': '1911'}
        )
        assert found == [
            {
                'type': '/type/author',
                'name': 'Mark Twain',
                'birth_date': '1835',
                'death_date': '1911',
            }
        ]
        assert load_book.find_entity(
            {'name': 'Mark Twain', 'birth_date': '1835', 'death_date': '1911'}
        ) is None

    def test_missing_date_falls_back_to_name(self, mock_site):
        mock_site.save(author(1, 'Mark Twain', birth_date='1835', death_date='1910'))
        assert load_book.find_author({'name': 'Mark Twain', 'birth_date': '1835'})[0][
            'key'
        ] == '/authors/OL1A'
        assert load_book.find_author({'name': 'Mark Twain', 'death_date': '1910'})[0][
            'key'
        ] == '/authors/OL1A'
        assert load_book.find_entity({'name': 'Mark Twain'})['key'] == '/authors/OL1A'

    def test_alternate_names(self, mock_site):
        mock_site.save(
            author(
                1,
                'Hubert Howe Bancroft',
                alternate_names=['HUBERT HOWE BANDCROFT'],
                birth_date='1832',
                death_date='1918.',
            )
        )
        found = load_book.find_author(
            {'name': 'Hubert Howe Bandcroft', 'birth_date': '1832', 'death_date': '1918'}
        )
        assert [a['key'] for a in found] == ['/authors/OL1A']
        # requires both dates:
        assert 'key' not in load_book.find_author(
            {'name': 'Hubert Howe Bandcroft', 'birth_date': '1832'}
        )[0]

    def test_surname(self, mock_site):
        mock_site.save(
            author(1, 'Arthur Conan Doyle', birth_date='1859', death_date='1930')
        )
        found = load_book.find_author(
            {'name': 'doyle, arthur conan', 'birth_date': '1859', 'death_date': '1930'}
        )
        assert [a['key'] for a in found] == ['/authors/OL1A']
        # surname path must not resolve when a date is missing or mismatched
        assert 'key' not in load_book.find_author({'name': 'Doyle', 'birth_date': '1859'})[0]
        assert 'key' not in load_book.find_author(
            {'name': 'Doyle', 'birth_date': '1859', 'death_date': '1931'}
        )[0]

    def test_wildcard_first_candidate_by_numeric_key(self, mock_site):
        mock_site.save(author(10, 'John Smith'))
        mock_site.save(author(2, 'John Dos Passos'))
        mock_site.save(author(1, 'John Steinbeck'))
        found = load_book.find_author({'name': 'John*'})
        assert [a['key'] for a in found] == [
            '/authors/OL1A',
            '/authors/OL2A',
            '/authors/OL10A',
        ]

    def test_wildcard_no_match_returns_candidate(self, mock_site):
        mock_site.save(author(1, 'Jane Austen'))
        found = load_book.find_author({'name': 'John*'})
        assert found == [{'type': '/type/author', 'name': 'John*'}]

    def test_no_match_preserves_fields(self, mock_site):
        found = load_book.find_author(
            {'name': 'Nobody Here', 'birth_date': '1835', 'death_date': '1910'}
        )
        assert found[0]['name'] == 'Nobody Here'
        assert found[0]['birth_date'] == '1835'
        assert found[0]['death_date'] == '1910'


def test_get_surname():
    assert load_book.get_surname('Twain, Mark') == 'Twain'
    assert load_book.get_surname('Mark Twain') == 'Twain'
    assert load_book.get_surname('Harper, John Murdoch, 1845-') == 'Harper'
    assert load_book.get_surname('Confucius') == 'Confucius'


def test_imported_author_matches_existing_case_insensitively(mock_site):
    mock_site.save(author(1, 'Mark Twain', birth_date='1835', death_date='1910'))
    rec = {
        'title': 'A Connecticut Yankee',
        'source_records': ['ia:xyz'],
        'publishers': ['Foo'],
        'authors': [{'name': 'Twain, Mark', 'birth_date': '1835', 'death_date': '1910'}],
    }
    reply = load_book.load(rec) if hasattr(load_book, 'load') else None
    keys = web.ctx.site.things({'type': '/type/author', 'name~': 'Mark Twain'})
    assert len(keys) == 1
